// Normaliza el payload de WhatsApp a texto para el agente (criterio B-3).
// Descarta silenciosamente lo que no sea un mensaje de usuario.

// La configuracion se arrastra ENTERA y no campo por campo. Antes se copiaba
// una lista fija, y agregar un campo al nodo `Config del negocio` no bastaba:
// el prompt lo leia como undefined y la instruccion nunca llegaba al modelo.
// Fue exactamente lo que paso con `estiloEmojis` y `tratamiento`.
const CLAVES_DEL_WEBHOOK = ['messages', 'contacts', 'metadata', 'messaging_product',
                            'object', 'entry', 'statuses', 'errors'];

const out = [];
for (const item of $input.all()) {
  const src = item.json;
  const msg = Array.isArray(src.messages) ? src.messages[0] : undefined;
  if (!msg) continue; // acuse de estado u otro evento

  const config = {};
  for (const [clave, valor] of Object.entries(src)) {
    if (!CLAVES_DEL_WEBHOOK.includes(clave)) config[clave] = valor;
  }

  // Filtro por pais de origen. Meta cobra el mensaje segun el pais del
  // DESTINATARIO, asi que responderle a un numero extranjero cuesta su tarifa,
  // que puede ser diez veces la boliviana. Se descarta ANTES de responder: no
  // se contesta y no se gasta. Lista vacia = se acepta cualquier origen.
  const prefijos = String(config.prefijosPermitidos ?? '')
    .split(',').map(p => p.trim()).filter(Boolean);
  if (prefijos.length && !prefijos.some(p => String(msg.from ?? '').startsWith(p))) {
    continue;
  }

  const tipo = msg.type ?? 'desconocido';
  let userInput = '';
  switch (tipo) {
    case 'text':
      userInput = msg.text?.body ?? '';
      break;
    case 'interactive': {
      const sel = msg.interactive?.list_reply ?? msg.interactive?.button_reply;
      userInput = `El cliente seleccionó la opción del menú: ${sel?.title ?? ''} (id: ${sel?.id ?? ''})`;
      break;
    }
    case 'button':
      userInput = `El cliente tocó el botón: ${msg.button?.text ?? ''}`;
      break;
    case 'image':
      userInput = 'AVISO_SISTEMA: el cliente envió una imagen. Agradécela y continúa el agendamiento.';
      break;
    default:
      userInput = `AVISO_SISTEMA: el cliente envió un mensaje de tipo "${tipo}" que no puedes leer. ` +
        'Respóndele cortésmente que por ahora atiendes por texto.';
  }

  const contacto = Array.isArray(src.contacts) ? src.contacts[0] : undefined;
  out.push({ json: {
    ...config,
    userInput,
    tipo,
    from: msg.from,
    nombrePerfil: contacto?.profile?.name ?? '',
  }});
}
return out;

// Separa la marca [TRANSFERIR] de la respuesta al cliente (criterio C-11).
const entradas = $('Normalizar entrada').all();
const cfg = $('Config del negocio').first().json;
const cierre = String(cfg.mensajeCierre ?? '').trim()
  || 'Gracias por escribirnos. Si necesita algo mas, escribame por aca.';
const falla = String(cfg.mensajeErrorTemporal ?? '').trim()
  || 'Disculpe, tuve un problema tecnico momentaneo. Me repite lo ultimo?';

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  // Emparejamiento por indice: nunca .first(), que le pondria el telefono del
  // primer cliente a la respuesta del segundo cuando llegan dos a la vez.
  const ent = (entradas[i] ?? entradas[entradas.length - 1]).json;
  const dato = items[i].json;

  // Gemini devuelve 500/503 en picos y entonces no llega `output`. Hay que
  // distinguirlo de una respuesta vacia: despedirse cuando en realidad se cayo
  // el modelo deja al cliente creyendo que la conversacion termino.
  const fallo = dato.error !== undefined || dato.output === undefined;
  const texto = String(dato.output ?? '').trim();
  const transferir = texto.includes('[TRANSFERIR]');
  let respuesta = texto.split('[TRANSFERIR]').join('').trim();

  // El nodo de WhatsApp rechaza un cuerpo vacio con 400 Bad request.
  const vacia = respuesta === '';
  if (fallo) respuesta = falla;
  else if (vacia) respuesta = cierre;


  // Marca si la respuesta AFIRMA que la cita quedo agendada. Se decide aca y
  // no en una expresion del nodo IF para poder probarlo: la trampa es que
  // "ya tiene reservada su cita" no es una confirmacion nueva sino un aviso
  // de que el horario esta ocupado, y disparar la compuerta ahi romperia una
  // conversacion correcta. Probado contra las frases reales del agente.
  // Solo cuentan las formas de HECHO CONSUMADO. "agendamos" y "reservamos"
  // salieron de la lista: en espanol son a la vez presente y pasado, y el
  // agente las usa para OFRECER ("con gusto agendamos tu cita"). El
  // 2026-08-29 esa ambiguedad disparo la compuerta en plena conversacion y le
  // dijo al cliente que no se pudo registrar una cita que nadie habia pedido.
  const CONFIRMA = /(ha sido|han sido|queda|quedó|quedo|fue|está|esta|ya está|ya esta)\s+(agendad|reservad|registrad|confirmad)|(agendé|reservé|registré)(?![a-záéíóúñ])/i;
  const YA_EXISTE = /\bya\s+(tiene|tienes|cuenta con|hay)/i;
  const afirmaAgendo = CONFIRMA.test(respuesta) && !YA_EXISTE.test(respuesta);

  out.push({ json: {
    respuesta,
    transferir,
    motivoTransferencia: transferir ? 'tres rechazos de horario consecutivos' : '',
    afirmaAgendo,
    respuestaVacia: vacia,
    falloModelo: fallo,
    from: ent.from,
    nombrePerfil: ent.nombrePerfil,
  }});
}
return out;

// COMPUERTA: no prometer una reserva que no exista.
// El agente puede afirmar que agendo aunque la herramienta haya fallado: ya
// paso el 2026-08-29, con un ID de calendario mal escrito. Una regla en el
// prompt es una sugerencia estadistica; esto es una comprobacion.
const previos = $('Procesar respuesta').all();
const cfg = $('Config del negocio').first().json;
const aviso = String(cfg.mensajeReservaNoConfirmada ?? '').trim()
  || 'Disculpe, no pude confirmar el registro de su cita. Le paso con recepcion.';

const VENTANA_MS = 5 * 60 * 1000;
const ahora = Date.now();

// Solo cuentan eventos REALES creados recien. Si el nodo de Calendar fallo,
// aca no llega ningun evento con id y la compuerta cierra, que es la
// direccion segura: preferimos derivar a una persona antes que mentir.
const recien = $input.all()
  .map(i => i.json)
  .filter(e => e && e.id)
  .filter(e => {
    const c = Date.parse(e.created || e.updated || '');
    return Number.isFinite(c) && (ahora - c) >= 0 && (ahora - c) < VENTANA_MS;
  });

// Con mas de un mensaje en la misma ejecucion no se puede atribuir el evento a
// un cliente concreto: no se promete nada y lo toma una persona.
const ambiguo = previos.length !== 1;
const item = previos[0].json;
const verificada = recien.length > 0 && !ambiguo;

if (verificada) {
  return [{ json: { ...item, reservaVerificada: true, eventoId: recien[0].id } }];
}
return [{ json: { ...item, respuesta: aviso, transferir: true, reservaVerificada: false,
  motivoTransferencia: 'el agente confirmo una cita que NO existe en el calendario' } }];

// El comercio no esta operativo (suspendido o dado de baja).
// PROHIBIDO revelar el motivo: el cliente final no tiene por que enterarse de
// que el negocio debe dinero. El texto es neutro y sale de Config del negocio.
// Se corta ANTES del agente, asi que un comercio suspendido no consume ni
// tokens ni llamadas al calendario.
const cfg = $('Config del negocio').first().json;
const aviso = String(cfg.mensajeComercioSuspendido ?? '').trim()
  || 'En este momento no podemos atenderte por este medio. Gracias por escribirnos.';

return $input.all().map(i => ({ json: {
  respuesta: aviso,
  transferir: false,
  comercioSuspendido: true,
  estadoComercio: cfg.estadoComercio,
  from: i.json.from,
  nombrePerfil: i.json.nombrePerfil,
}}));
